package com.yuegang.zhihui.training.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.training.application.*;import com.yuegang.zhihui.training.security.*;import jakarta.servlet.http.*;import jakarta.validation.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/training/assignments")public final class ScopedAssignmentController{private final ScopedAssignmentService service;private final TrainingUserResolver users;public ScopedAssignmentController(ScopedAssignmentService s,TrainingUserResolver u){service=s;users=u;}@PostMapping("/scoped")ApiResponse<ScopedAssignmentResult>assign(@Valid @RequestBody CreateScopedAssignmentRequest b,HttpServletRequest r){return ApiResponse.success(service.assign(users.requirePermission(r,"training:assignment:create"),b),TraceIdResolver.resolve(r));}}
